/**
 * Generates 5 onboarding Excel files at different complexity levels.
 * Run:  node artifacts/api-server/scripts/gen-test-complexity-suite.mjs
 *
 * Level 1  — Minimal          : 3 staff, 1 project, 2 assignments
 * Level 2  — Basic            : 8 staff, 2 divisions, 3 projects, 4 assignments
 * Level 3  — Medium           : 15 staff, 3 divisions, 4 projects + 3 opps, 10 assignments
 * Level 4  — Full Org         : 25 staff, 4 divisions, 6 projects + 4 opps + 2 leads, 18 assignments
 * Level 5  — Stress + Blanks  : 35 staff with deliberate gaps, 8 projects + 5 opps + 3 leads,
 *                               26 assignments — exercises defaults + missing-data handling
 */
import ExcelJS from "exceljs";
import path from "path";
import fs from "fs";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUT = path.resolve(__dirname, "../../../attached_assets/test-excels");
fs.mkdirSync(OUT, { recursive: true });

// ── Helpers ────────────────────────────────────────────────────────────────────
const HEAD_FILL = { type: "pattern", pattern: "solid", fgColor: { argb: "FF1F3A5F" } };
const HEAD_FONT = { bold: true, color: { argb: "FFFFFFFF" }, size: 11 };

function addSheet(wb, name, headers, rows) {
  const ws = wb.addWorksheet(name, { views: [{ state: "frozen", ySplit: 1 }] });
  ws.columns = headers.map((h) => ({ header: h, key: h, width: Math.max(h.length + 4, 16) }));
  ws.getRow(1).eachCell((c) => { c.fill = HEAD_FILL; c.font = HEAD_FONT; c.alignment = { vertical: "middle" }; });
  ws.getRow(1).height = 22;
  rows.forEach((r) => ws.addRow(headers.map((h) => r[h] ?? "")));
  ws.autoFilter = { from: { row: 1, column: 1 }, to: { row: 1, column: headers.length } };
}

const TEAM_H    = ["Division","Department","Role","Billing Rate","Labor Rate","Cost Rate","Job Title","Job Profile","Login Email","Full Name","Email","Password","Access Level","Manager","Start Date","End Date","Is Manager"];
const CLIENTS_H = ["Type","Company Name","Contacts","Client Rep","CRM Health","Market Sector","Project Title","Job ID","Project Type","Service Type","Contract Value","Contract Type","Chance of Success","Status","Division","Department","Start Date","End Date"];
const ASSIGN_H  = ["Project","Team Member","Start Date","End Date","Allocation %","Total Hours","Type","Billing Rate"];

async function write(filename, setupFn) {
  const wb = new ExcelJS.Workbook();
  wb.creator = "RMOne Onboarding Test Suite";
  wb.created = new Date();
  setupFn(wb);
  const fp = path.join(OUT, filename);
  await wb.xlsx.writeFile(fp);
  console.log("✓", fp);
}

